/** 半角数字を全角数字にする（パッケージ見出し「ガチ文化祭２０２６」の表記用） */
export const toFullWidthDigits = (s: string) =>
  s.replace(/[0-9]/g, (d) => String.fromCharCode(d.charCodeAt(0) + 0xfee0));
